\encoding UTF8
\set ON_ERROR_STOP on
-- NEUROFOCUS - Importacion de dataset sintetico (300 registros)
-- ADVERTENCIA: este script LIMPIA los datos de las 9 tablas antes de cargar el dataset.
-- No cambia la estructura de las tablas.
BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

TRUNCATE TABLE logros_usuario, progreso_diario, resultados_ejercicios, sesiones_estudio, actividades_calendario, tareas, logros, ejercicios, usuarios RESTART IDENTITY CASCADE;

-- 30 usuarios

-- 70 tareas

-- 40 actividades de calendario

-- 60 sesiones de estudio; interrumpida -> cancelada por restriccion de la BD

-- 20 ejercicios; tipo del Excel -> categoria de la BD. dificultad=medio porque el Excel no trae dificultad.

-- 30 resultados de ejercicios; tiempo_segundos queda NULL porque el Excel no trae ese dato

-- 30 registros de progreso diario

-- 8 logros; criterio del Excel -> condicion_clave; icono=trophy por defecto

-- 12 relaciones usuario-logro; id_logro_usuario se omite porque la PK real es compuesta (id_usuario,id_logro)

-- Sincronizar secuencias SERIAL
SELECT setval(pg_get_serial_sequence('usuarios','id_usuario'), COALESCE((SELECT MAX(id_usuario) FROM usuarios),1), true);
SELECT setval(pg_get_serial_sequence('tareas','id_tarea'), COALESCE((SELECT MAX(id_tarea) FROM tareas),1), true);
SELECT setval(pg_get_serial_sequence('actividades_calendario','id_actividad'), COALESCE((SELECT MAX(id_actividad) FROM actividades_calendario),1), true);
SELECT setval(pg_get_serial_sequence('sesiones_estudio','id_sesion'), COALESCE((SELECT MAX(id_sesion) FROM sesiones_estudio),1), true);
SELECT setval(pg_get_serial_sequence('ejercicios','id_ejercicio'), COALESCE((SELECT MAX(id_ejercicio) FROM ejercicios),1), true);
SELECT setval(pg_get_serial_sequence('resultados_ejercicios','id_resultado'), COALESCE((SELECT MAX(id_resultado) FROM resultados_ejercicios),1), true);
SELECT setval(pg_get_serial_sequence('progreso_diario','id_progreso'), COALESCE((SELECT MAX(id_progreso) FROM progreso_diario),1), true);
SELECT setval(pg_get_serial_sequence('logros','id_logro'), COALESCE((SELECT MAX(id_logro) FROM logros),1), true);

-- Verificacion de cantidades
SELECT 'usuarios' tabla, COUNT(*) cantidad FROM usuarios UNION ALL SELECT 'tareas',COUNT(*) FROM tareas UNION ALL SELECT 'actividades_calendario',COUNT(*) FROM actividades_calendario UNION ALL SELECT 'sesiones_estudio',COUNT(*) FROM sesiones_estudio UNION ALL SELECT 'ejercicios',COUNT(*) FROM ejercicios UNION ALL SELECT 'resultados_ejercicios',COUNT(*) FROM resultados_ejercicios UNION ALL SELECT 'progreso_diario',COUNT(*) FROM progreso_diario UNION ALL SELECT 'logros',COUNT(*) FROM logros UNION ALL SELECT 'logros_usuario',COUNT(*) FROM logros_usuario ORDER BY tabla;

COMMIT;
